<script setup>
/**
 * Carte de Madagascar : le littoral est la géométrie réelle du pays
 * (Natural Earth 10 m, domaine public), projetée en équirectangulaire
 * corrigée par cos(latitude) — pas un tracé approximatif à main levée.
 * Les repères sont projetés par les mêmes formules, donc aux vraies
 * positions relatives sur ce contour.
 */
import { computed } from 'vue'

const props = defineProps({
    destinations: { type: Array, default: () => [] },
    active: { type: String, default: '' },
})

defineEmits(['activate'])

/*
 * Positions projetées depuis les coordonnées réelles avec la projection
 * déduite du littoral :  x = 46.100·lon − 1982.1   y = 48.574·|lat| − 531.5
 * (elle reproduit les six repères d'origine à 0,03 px près).
 *
 * `side` ('left' | 'right' | 'top') et `dy` placent l'étiquette à la main :
 * à onze repères, la règle automatique « à droite si x > 180 » faisait se
 * chevaucher Antananarivo, Ampefy et Andasibe, qui sont sur la même bande
 * horizontale. Antananarivo passe au-dessus de son repère, faute de place
 * de part et d'autre.
 */
const PINS = {
    'nosy-be':      { x: 242.7, y: 115.5, side: 'right' },
    'majunga':      { x: 153.3, y: 232.1, side: 'left' },
    'sainte-marie': { x: 316.0, y: 294.3, side: 'right' },
    'foulpointe':   { x: 299.9, y: 327.4, side: 'right' },
    'tamatave':     { x: 295.4, y: 350.1, side: 'right' },
    'antananarivo': { x: 208.0, y: 385.5, side: 'top', dy: -18 },
    'andasibe':     { x: 250.1, y: 388.0, side: 'right' },
    'ampefy':       { x: 171.7, y: 392.9, side: 'left', dy: 16 },
    'antsirabe':    { x: 186.0, y: 433.7, side: 'left' },
    'morondava':    { x: 59.4,  y: 453.7, side: 'left' },
    'tulear':       { x: 31.1,  y: 602.7, side: 'left' },
}

const plotted = computed(() =>
    props.destinations
        .filter((d) => PINS[d.slug])
        .map((d) => ({ ...d, ...PINS[d.slug] }))
)
</script>

